-- Career completeness, part 2b: Finance, Government, Law, Management.
-- Same columns as part 2a. Careers that have an official route from their governing body
-- (chartered accountant, IFS, IRS, navy officer...) get a full description and where they
-- work; their steps stay the official ones shown on the page.

update public.careers c set
  description = coalesce(v.descr, c.description),
  path_steps = string_to_array(v.steps, ' | '),
  top_employers = string_to_array(v.emp, ' | '),
  related_college_slugs = case when v.cols is null then c.related_college_slugs else string_to_array(v.cols, ' ') end
from (values
  -- Finance
  ('chartered-accountant', 'Audits company accounts, prepares and files taxes, and advises businesses on finance, GST and compliance. Only a member of ICAI can sign audit reports in India, which makes the CA one of the most trusted finance qualifications.',
   null, 'Big Four firms (Deloitte, PwC, EY, KPMG) | Mid-size CA firms | Banks and NBFCs | Corporate finance teams | Own practice', null),
  ('economist', 'Studies how people, businesses and governments use resources, and uses data to explain trends such as inflation, jobs and growth. Advises governments, central banks, companies and research bodies on policy and decisions.',
   'Class 12 (Mathematics strongly recommended) | B.A. / B.Sc Economics through CUET UG | M.A. Economics (Delhi School of Economics, JNU, MSE through their entrances) | Learn statistics, econometrics and tools like R or Stata | Clear the UPSC Indian Economic Service, RBI Grade B (DEPR), or join research firms | PhD for academic and senior research roles',
   'RBI | NITI Aayog | Indian Economic Service | World Bank and IMF | Think tanks (NCAER, ICRIER) | Banks and consulting firms', 'dse-delhi jnu mse-chennai igidr-mumbai isi-kolkata srcc-delhi'),
  ('financial-analyst', 'Studies company accounts, markets and the economy to judge where money should be invested, and builds financial models and reports that guide companies, banks and investors.',
   'Class 12 (Commerce or Mathematics helps) | B.Com, BBA, B.A. Economics or B.Tech | Learn Excel, accounting and financial modelling | Take CFA Level 1 or an MBA in Finance (CAT, XAT) | Join as an analyst in a bank, fund or corporate finance team | Grow to senior analyst, then portfolio or finance manager',
   'Goldman Sachs | JP Morgan | Morgan Stanley | HDFC Bank | ICICI Securities | Mutual funds | Corporate finance teams | Rating agencies (CRISIL)', null),
  ('investment-banker', 'Helps companies raise money through shares and bonds (IPOs), advises on mergers and acquisitions, and values businesses. The work is demanding, with long hours, but among the best paid in finance.',
   'Class 12 | B.Com, BBA, B.Tech or Economics from a strong college | Learn financial modelling and valuation | MBA in Finance from a top B-school (CAT, XAT, GMAT) and / or CFA | Summer internship at an investment bank | Join as an analyst or associate, then grow to vice president and director',
   'Goldman Sachs | JP Morgan | Morgan Stanley | Kotak Investment Banking | Axis Capital | ICICI Securities | Avendus', null),
  ('quantitative-analyst', null,
   'Class 12 with Mathematics | B.Tech / B.Stat / B.Math (JEE Advanced, ISI or CMI entrance) | Strong probability, statistics and programming (Python, C++) | Solve quant puzzles and competitive programming | Internship at a trading firm or bank | Join as a quant researcher or developer; a master''s or PhD helps',
   'Tower Research | Graviton | Optiver | Goldman Sachs | JP Morgan | WorldQuant | Hedge funds and HFT firms', null),

  -- Government
  ('airforce-officer', 'Leads Indian Air Force operations as a flying officer (pilot), in technical branches (aeronautical engineering) or in ground duties (administration, logistics, education). Officers command people and aircraft and get excellent training, pay and allowances.',
   'Class 12 with Physics and Mathematics (for flying branch through NDA) or graduation (for AFCAT / CDS) | Clear NDA, AFCAT or CDS | Clear the AFSB interview, the pilot aptitude test (CPSS) for flying, and the medical | Train at NDA and / or the Air Force Academy, Dundigal | Get commissioned as a Flying Officer | Rise through Flight Lieutenant, Squadron Leader and above',
   'Indian Air Force', null),
  ('army-officer', 'Leads soldiers in the Indian Army in combat arms (infantry, armoured, artillery), support arms (engineers, signals) and services. Officers handle training, operations and the welfare of their men, with steady promotion, pay and respect.',
   'Class 12 (for NDA) or graduation (for CDS) | Clear NDA or CDS (or a technical / NCC / JAG entry) | Clear the 5-day SSB interview and the medical | Train at NDA and IMA Dehradun (or OTA Chennai for Short Service) | Get commissioned as a Lieutenant | Rise through Captain, Major, Lieutenant Colonel and above',
   'Indian Army', null),
  ('central-civil-services-officer-group-a', null,
   'Graduation in any discipline | Clear UPSC Civil Services Prelims, Mains and the interview | Get allotted a Group A service (for example IRTS, IDAS, ICAS, IP&TAFS) based on rank and preference | Foundation course at LBSNAA, then training at your service''s academy | Join as an Assistant Director, Assistant Commissioner or similar | Rise to Joint Secretary and above',
   'Ministries and departments of the Government of India | Indian Railways | Defence Accounts Department | Comptroller and Auditor General', null),
  ('customs-officer', 'Checks goods entering and leaving India at ports, airports and borders, collects customs duty and GST on imports, and stops smuggling of drugs, gold and wildlife. Officers range from Inspectors (SSC CGL) to IRS (Customs and Indirect Taxes) officers (UPSC).',
   'Graduation in any discipline | For Inspector: clear SSC CGL and choose Customs / Central Excise Inspector | For officer posts: clear UPSC Civil Services and get the IRS (Customs and Indirect Taxes) | Training at NACIN | Postings at ports, airports, ICDs and customs preventive units | Promotion to Superintendent, Assistant Commissioner and higher',
   'Central Board of Indirect Taxes and Customs (CBIC) | Directorate of Revenue Intelligence | Customs houses at ports and airports', null),
  ('diplomat', 'Represents India abroad in embassies and high commissions: negotiates with other countries, protects Indians overseas, issues visas and passports, and promotes trade and culture. Most career diplomats are Indian Foreign Service officers.',
   'Graduation in any discipline | Clear UPSC Civil Services and get the Indian Foreign Service (only the top ranks get it) | Foundation course at LBSNAA, then training at the Sushma Swaraj Institute of Foreign Service | Learn a foreign language assigned to you | First posting abroad as Third Secretary | Rise to Ambassador or High Commissioner',
   'Ministry of External Affairs | Indian embassies and high commissions | Permanent Mission to the UN', null),
  ('election-commissioner', 'Runs elections in India as one of the members of the Election Commission of India, a constitutional body. Election Commissioners are appointed by the President, usually from very senior civil servants; it is not an entry-level career that students can join directly.',
   null, 'Election Commission of India | State Election Commissions', null),
  ('forest-officer', 'Protects forests and wildlife, manages national parks and tiger reserves, prevents poaching and illegal felling, and works with forest communities. Officers come through the UPSC Indian Forest Service or state forest services.',
   'Graduation in a science subject (Botany, Zoology, Agriculture, Forestry, Engineering and others) | Clear the UPSC Indian Forest Service exam (Civil Services Prelims, then IFoS Mains and interview) | Training at the Indira Gandhi National Forest Academy, Dehradun | Posting as Assistant / Divisional Forest Officer | Rise to Conservator and Principal Chief Conservator of Forests',
   'State Forest Departments | Ministry of Environment, Forest and Climate Change | National Tiger Conservation Authority | Wildlife Institute of India', 'ifri-dehradun wii-dehradun fore-delhi'),
  ('ifs-officer', 'An Indian Foreign Service officer represents India in its embassies abroad and at the Ministry of External Affairs, handling diplomacy, trade relations, consular services and India''s image overseas. Selected through UPSC Civil Services, among its top ranks.',
   null, 'Ministry of External Affairs | Indian embassies, high commissions and consulates | Permanent Missions to the UN and other bodies', null),
  ('intelligence-officer', 'Collects and analyses information about threats to India''s security, such as terrorism, espionage and organised crime. Most join the Intelligence Bureau as ACIO through its own exam, or as IPS / CSE officers posted to intelligence agencies.',
   'Graduation in any discipline | Clear the Intelligence Bureau ACIO exam (or SSC CGL for some IB posts, or UPSC Civil Services for officer-level postings) | Clear the interview and background verification | Training at the IB training school | Work in field units or analysis desks | Promotion to Deputy Central Intelligence Officer and above',
   'Intelligence Bureau | Research and Analysis Wing | National Investigation Agency | State intelligence units', null),
  ('irs-officer', 'An Indian Revenue Service officer collects the central government''s taxes: income tax for IRS (IT), or customs and GST for IRS (C&IT). Officers investigate tax evasion, conduct searches and hear appeals. Selected through UPSC Civil Services.',
   null, 'Income Tax Department (CBDT) | Central Board of Indirect Taxes and Customs | Directorate of Enforcement', null),
  ('municipal-commissioner', 'Heads a city''s municipal corporation: runs water supply, roads, sanitation, property tax, building permissions and city planning. Usually a senior IAS officer or a state civil service officer posted to the city.',
   'Graduation in any discipline | Clear UPSC Civil Services (IAS) or your State PSC civil services exam | Training and early postings as SDM / District Collector or in urban development | Get posted as Municipal Commissioner of a city (usually after several years) | Lead the city''s administration',
   'Municipal corporations | State Urban Development Departments | Smart City missions', null),
  ('navy-officer', 'Leads Indian Navy operations at sea, in the air and ashore, in executive (warships, submarines, aviation), engineering, electrical and education branches. Officers command ships and crews and protect India''s coasts and sea routes.',
   null, 'Indian Navy', null),
  ('paramilitary-force-officer-capf', null,
   'Graduation in any discipline (age 20-25) | Clear the UPSC CAPF (Assistant Commandant) exam: written papers, physical tests, interview and medical | Or clear SSC CPO for Sub-Inspector posts | Basic training at your force''s academy | Lead a company as Assistant Commandant | Rise to Deputy Commandant, Commandant and higher',
   'Border Security Force | CRPF | CISF | ITBP | Sashastra Seema Bal', null),
  ('policy-analyst', 'Researches problems such as health, education, jobs or climate, studies data and laws, and recommends what governments should do. Works in think tanks, government advisory bodies, NGOs and international organisations.',
   'Graduation in economics, political science, law, public policy or any field | Master''s in Public Policy, Economics or Development Studies | Learn data analysis (Excel, R or Python) and policy writing | Fellowships and internships (LAMP, CM fellowships, NITI Aayog internships) | Join a think tank, ministry advisory team or NGO | Grow to senior fellow or policy lead',
   'NITI Aayog | Think tanks (PRS Legislative Research, CPR, ORF) | World Bank and UN agencies | State government policy units | Consulting firms', 'jnu tiss-mumbai iipa-delhi ashoka-university dse-delhi azim-premji-university igidr-mumbai'),
  ('ssc-government-assistant-clerk', null,
   'Class 12 (for CHSL posts such as LDC, JSA and DEO) or graduation (for CGL assistant posts) | Clear the SSC CHSL or SSC CGL exam (computer-based test plus a typing or skill test) | Document verification and allotment of a ministry or department | Join as Lower Division Clerk, Junior Secretariat Assistant or Assistant | Departmental promotion to Upper Division Clerk, Assistant and Section Officer',
   'Central government ministries and departments | Employees'' Provident Fund Organisation | Central Secretariat | Subordinate offices across India', null),
  ('state-psc-officer', 'Serves in a state''s administration as Deputy Collector / SDM, DSP, Commercial Tax Officer, Block Development Officer and similar posts, selected through the State Public Service Commission''s combined exam.',
   'Graduation in any discipline | Clear your State PSC combined exam (for example UPPSC PCS, BPSC CCE, RPSC RAS, MPSC): Prelims, Mains and interview | Choose a post according to rank and preference | Training at the state administrative or police academy | Join as SDM, DSP or an equivalent officer | Promotion, and in many states induction into IAS / IPS later in service',
   'State government departments | District administrations | State police', null),

  -- Law
  ('constitutional-lawyer', 'Specialises in the Constitution: fundamental rights, the powers of governments and courts, and public interest cases. Argues writ petitions in High Courts and the Supreme Court, and advises governments and organisations.',
   'Class 12 in any stream | 5-year BA LLB through CLAT, AILET or a university entrance (or a 3-year LLB after graduation) | Enrol with the State Bar Council and pass the All India Bar Exam | Work as a junior with a senior advocate in High Court or Supreme Court practice | Optional: LLM in Constitutional Law | Argue constitutional cases independently',
   'Supreme Court and High Court chambers | Law firms with public law practices | Government law officers | Human rights organisations | Law schools', null),
  ('corporate-lawyer', 'Advises companies on contracts, mergers and acquisitions, investments, fundraising, compliance and disputes. Most work in law firms or in-house legal teams rather than in courts.',
   'Class 12 in any stream | BA LLB / BBA LLB through CLAT or a university entrance | Internships at corporate law firms during college | Enrol with the Bar Council and pass the All India Bar Exam | Join a law firm as an associate or a company''s legal team | Grow to senior associate, partner or general counsel; Company Secretary or LLM can help',
   'Cyril Amarchand Mangaldas | AZB & Partners | Khaitan & Co | Trilegal | Shardul Amarchand Mangaldas | Company legal teams', null),
  ('criminal-lawyer', 'Defends people accused of crimes, or prosecutes them on behalf of the state. Works in trial courts, sessions courts and High Courts on bail, trials and appeals under the new criminal laws (BNS, BNSS).',
   'Class 12 in any stream | BA LLB through CLAT or a university entrance, or LLB after graduation | Enrol with the State Bar Council and pass the All India Bar Exam | Work as a junior in a criminal practice in district courts | Build experience in bail, trials and appeals | Practise independently, or become a public prosecutor',
   'Criminal law chambers | District and Sessions courts | Legal aid services | Prosecution departments', null),
  ('cyber-lawyer', 'Handles legal issues of the digital world: cybercrime, data protection under the DPDP Act, IT Act cases, online fraud, and contracts for technology companies.',
   'Class 12 in any stream | BA LLB / B.Tech LLB through CLAT or a university entrance | Courses in cyber law and data protection | Internships with tech law firms or cybercrime cells | Enrol with the Bar Council | Work in a law firm, tech company or as an independent cyber law practitioner',
   'Technology law firms | IT companies'' legal teams | Cybercrime cells and CERT-In | Data protection consultancies', null),
  ('environmental-lawyer', 'Uses the law to protect the environment: pollution, forests, wildlife, climate and project clearances. Argues cases in the National Green Tribunal and High Courts and advises companies and NGOs.',
   'Class 12 in any stream | BA LLB through CLAT or a university entrance | Electives and moot courts in environmental law | Enrol with the Bar Council | Work with an environmental law practice, NGO or the NGT bar | Optional: LLM in Environmental Law',
   'National Green Tribunal practitioners | Environmental NGOs (CSE, WWF India) | Law firms | Company compliance teams | Pollution control boards', null),
  ('family-lawyer', 'Handles divorce, maintenance, child custody, adoption, domestic violence and inheritance cases, mostly in family courts. Needs sensitivity as much as legal skill.',
   'Class 12 in any stream | BA LLB through CLAT or a university entrance, or LLB after graduation | Enrol with the State Bar Council and pass the All India Bar Exam | Work as a junior in family court practice | Learn mediation and counselling skills | Build your own practice',
   'Family law chambers | Family courts | Legal aid services | Mediation centres', null),
  ('human-rights-lawyer', 'Fights for people whose rights are violated: prisoners, workers, women, children, minorities and displaced communities. Works through public interest litigation, legal aid and advocacy.',
   'Class 12 in any stream | BA LLB through CLAT or a university entrance | Internships with human rights organisations and legal aid clinics | Enrol with the Bar Council | Work with an NGO, legal aid body or a senior advocate | Optional: LLM in Human Rights',
   'Human rights NGOs (HRLN, Amnesty) | National and State Human Rights Commissions | Legal aid services | UN agencies', null),
  ('ip-lawyer', 'Protects inventions, brands and creative work through patents, trademarks, copyrights and designs, and handles infringement cases. A science or engineering background helps in patent work.',
   'Class 12 (science helps for patents) | BA LLB, or B.Tech followed by LLB | Courses in intellectual property law | Enrol with the Bar Council; clear the Patent Agent Exam for patent filing | Join an IP law firm | Grow to senior associate or partner',
   'IP law firms (Anand and Anand, Remfry and Sagar) | Pharma and technology companies | Indian Patent Office | Media and entertainment companies', null),
  ('lawyer', 'Gives legal advice and represents clients in courts and tribunals in civil, criminal, corporate or family matters. After a law degree and Bar Council enrolment, lawyers either practise in courts or work in firms and companies.',
   'Class 12 in any stream | 5-year integrated LLB through CLAT, AILET or a university entrance, or a 3-year LLB after graduation | Internships with advocates, firms and courts | Enrol with the State Bar Council and pass the All India Bar Exam | Work as a junior advocate or associate | Specialise and build your own practice',
   'Law firms | Courts (as practising advocates) | Company legal teams | Government legal departments | Judiciary (after judicial services exams)', null),
  ('legal-advisor', 'Advises a company, government department or organisation on the legal side of its decisions: contracts, compliance, employment, property and disputes, and works with outside lawyers when needed.',
   'Class 12 in any stream | LLB (5-year or 3-year) | Enrol with the Bar Council | Gain 3-5 years in a law firm or in-house team | Optional: Company Secretary qualification or LLM | Join as legal advisor / legal manager, then head of legal',
   'Company legal teams | Banks and insurance companies | PSUs and government departments | NGOs', null),
  ('notary', 'Certifies documents, signatures and affidavits so they can be used in courts and abroad. A notary is appointed by the central or state government under the Notaries Act, from advocates with long practice.',
   'Become an advocate: LLB and enrolment with the Bar Council | Practise law for at least 10 years (7 years for some categories) | Apply to the central or state government when notary posts are notified | Clear the interview | Get your certificate of practice and register',
   'Self-employed notarial practice | Courts and registration offices', null),
  ('public-prosecutor', 'Represents the state in criminal cases, presenting evidence against the accused in sessions and High Courts. Assistant Public Prosecutors are recruited by state PSCs; senior posts are filled from experienced advocates.',
   'Class 12 in any stream | LLB (5-year or 3-year) | Enrol with the Bar Council and practise in criminal courts | Clear your State PSC Assistant Public Prosecutor exam (some states need 2-7 years of practice) | Training and posting in a district court | Rise to Additional and Public Prosecutor',
   'State Prosecution Departments | CBI and NIA prosecution wings | Courts', null),
  ('tax-lawyer', 'Advises on income tax, GST and international tax, and represents clients before tax authorities, tribunals (ITAT) and courts. Works closely with chartered accountants.',
   'Class 12 (Commerce helps) | BA LLB / B.Com LLB, or LLB after B.Com | Courses in tax law; CA or CS helps | Enrol with the Bar Council | Join a tax practice or the tax team of a law or Big Four firm | Appear before ITAT, High Courts and GST authorities',
   'Big Four tax practices | Law firms (Lakshmikumaran and Sridharan) | Company tax teams | Own practice', null),

  -- Management
  ('business-manager', null,
   'Graduation in any field (BBA or B.Com helps) | Work for 1-3 years to understand a business | MBA through CAT, XAT, SNAP, NMAT or MAH CET | Summer internship and placement as a management trainee or associate | Manage a team, product line or business unit | Grow to general manager or business head',
   'FMCG companies (HUL, ITC, P&G) | Tata Group | Reliance | Consulting firms | Startups | Banks', null),
  ('entrepreneur', 'Starts and runs their own business: spots a problem people will pay to solve, builds a product or service, finds customers, hires a team and raises money. There is no fixed route, but skills and experience matter.',
   'Study anything (business, engineering or design help) | Work in a startup or company to learn how businesses run | Find a real problem and test it with a small first version | Register the company, build a team and find first customers | Use incubators, government schemes (Startup India) and investors to grow | Scale the business',
   'Self-employed (own company) | Startup incubators (IIT, IIM, T-Hub) | Startup India', 'iim-ahmedabad iim-bangalore isb-hyderabad iit-bombay iit-delhi'),
  ('hotel-manager', 'Runs a hotel or resort: front office, housekeeping, food and beverage, sales and guest experience, so that guests are happy and the hotel is profitable. Starts with training in hotel management.',
   null, 'Taj (IHCL) | ITC Hotels | Oberoi | Marriott | Hyatt | Accor | OYO and resort chains', null),
  ('hr-manager', 'Looks after a company''s people: hiring, training, pay and benefits, performance reviews, employee relations and labour-law compliance. Good HR helps a company keep talented staff.',
   'Graduation in any field (BBA, psychology or commerce helps) | MBA / PGDM in HR through CAT, XAT or TISSNET | Summer internship in an HR team | Join as an HR executive or management trainee | Specialise in recruitment, learning, compensation or HR business partnering | Grow to HR head',
   'Tata Group | Infosys | TCS | HUL | Deloitte | Amazon | Banks | Startups', null),
  ('marketing-manager', 'Decides how a company reaches and wins customers: market research, branding, advertising, digital and social media campaigns, pricing and launches.',
   'Graduation in any field (BBA or B.Com helps) | MBA in Marketing through CAT, XAT, SNAP or NMAT | Learn digital marketing, analytics and branding | Summer internship and placement as a management trainee or brand associate | Manage a brand or campaign | Grow to marketing head or chief marketing officer',
   'HUL | P&G | Nestle | Amazon | Flipkart | Advertising agencies | Startups', null)
) as v(slug, descr, steps, emp, cols)
where c.slug = v.slug;
